"use client";
import { useState } from "react";
import "./InterestRate.css";
import { FaFilePdf, FaDownload, FaCalendarAlt } from "react-icons/fa";

export default function InterestRate() {
  const currentRates = {
    effectiveDate: "2080/10/01",
    savings: [
      { name: "Group Saving", rate: "7.5%" },
      { name: "Personal Saving", rate: "7.5%" },
      { name: "Pension/Child Saving", rate: "9.0%" },
    ],
    loans: [
      { name: "General Loan", rate: "14.38" },
      { name: "Micro-Enterprise Loan", rate: "14." },
    ],
  };

  const pdfArchive = [
    { year: "2082/83", months: ["Chaitra", "Falgun", "Magh", "Poush", "Mangsir"] },
    { year: "2081/82", months: ["Full Year Archive"] },
    { year: "2080/81", months: ["Full Year Archive"] },
  ];

  const [selectedYear, setSelectedYear] = useState(pdfArchive[0].year);

  const activeYearData = pdfArchive.find((a) => a.year === selectedYear);

  return (
    <div className="interest-page">
      
      {/* HEADER */}
      <div className="interest-hero">
        <h1>Rates & Charges</h1>
        <p>Transparent and regulated financial services</p>
      </div>

      <div className="interest-content">

        {/* SIDEBAR */}
        <aside className="archive-sidebar">
          <h3>
            <FaCalendarAlt /> Archive
          </h3>

          <ul>
            {pdfArchive.map((item) => (
              <li
                key={item.year}
                className={selectedYear === item.year ? "active" : ""}
                onClick={() => setSelectedYear(item.year)}
              >
                F.Y. {item.year}
              </li>
            ))}
          </ul>
        </aside>

        {/* MAIN */}
        <main className="details-main">

          {/* SUMMARY */}
          <div className="current-summary">
            <h2>Interest Rates (Effective: {currentRates.effectiveDate})</h2>

            <div className="rate-brief-grid">
              <div className="brief-box">
                <span>Savings (Max)</span>
                <h4>7.5%</h4>
              </div>

              <div className="brief-box">
                <span>Loan (Max)</span>
                <h4>14.38%</h4>
              </div>
            </div>
          </div>

          {/* DETAILS */}
          <div className="details-table">
            <h3>Detailed Interest Breakdown</h3>

            <div className="table-grid">
              
              <div className="table-box">
                <h4>Savings</h4>
                <ul>
                  {currentRates.savings.map((item, i) => (
                    <li key={i}>
                      <span>{item.name}</span>
                      <span>{item.rate}</span>
                    </li>
                  ))}
                </ul>
              </div>

              <div className="table-box">
                <h4>Loans</h4>
                <ul>
                  {currentRates.loans.map((item, i) => (
                    <li key={i}>
                      <span>{item.name}</span>
                      <span>{item.rate}</span>
                    </li>
                  ))}
                </ul>
              </div>

            </div>
          </div>

          {/* PDF */}
          <div className="pdf-section">
            <h3>Interest Notices ({selectedYear})</h3>

            <div className="pdf-list">
              {activeYearData?.months.map((month, index) => (
                <div key={index} className="pdf-card">
                  
                  <div className="pdf-info">
                    <FaFilePdf className="pdf-icon-red" />
                    <span>{month}</span>
                  </div>

                  <a
                    href={`/assets/pdf/interest/rate-${selectedYear.replace("/", "-")}-${month.toLowerCase()}.pdf`}
                    target="_blank"
                    rel="noreferrer"
                    className="btn-download"
                  >
                    <FaDownload /> Download
                  </a>

                </div>
              ))}
            </div>
          </div>

        </main>
      </div>
    </div>
  );
}
